WITH with_windows AS (SELECT id, budget, AVG(budget) OVER w_grp last4_avg_budget, COUNT(budget) OVER w_grp last4_count_budget, MAX(budget) OVER w_grp last4_max_budget, LEAD(budget, 2) OVER w_grp_2 next_budget FROM departments WINDOW w_grp AS (PARTITION BY dept_name, location ORDER BY budget ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY dept_name, location ORDER BY budget ASC, id ASC)) SELECT id, budget, last4_avg_budget, last4_max_budget, next_budget FROM with_windows ORDER BY budget ASC;
